using OpenInet=void*(WINAPI*)(LPCWSTR,DWORD,LPCWSTR,LPCWSTR,DWORD);using ConnectInet=void*(WINAPI*)(void*,LPCWSTR,unsigned short,LPCWSTR,LPCWSTR,DWORD,DWORD,DWORD_PTR);using RequestInet=void*(WINAPI*)(void*,LPCWSTR,LPCWSTR,LPCWSTR,LPCWSTR,LPCWSTR*,DWORD,DWORD_PTR);using SendInet=BOOL(WINAPI*)(void*,LPCWSTR,DWORD,LPVOID,DWORD);using QueryInet=BOOL(WINAPI*)(void*,DWORD,LPVOID,LPDWORD,LPDWORD);using ReadInet=BOOL(WINAPI*)(void*,LPVOID,DWORD,LPDWORD);using CloseInet=BOOL(WINAPI*)(void*);using SetInet=BOOL(WINAPI*)(void*,DWORD,LPVOID,DWORD);using OptionInet=BOOL(WINAPI*)(void*,DWORD,LPVOID,LPDWORD);
struct Server {
 SOCKET listener=INVALID_SOCKET;std::atomic<SOCKET> peer{INVALID_SOCKET};std::atomic<bool> stop{false},valid{true};std::atomic<unsigned> requests{0};std::thread worker;unsigned short port=0;std::string payload="Hollowwake-"+std::to_string(GetTickCount64());
 Server(){listener=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);Check(listener!=INVALID_SOCKET,"Original HTTP listener failed");sockaddr_in address={};address.sin_family=AF_INET;address.sin_addr.s_addr=htonl(INADDR_LOOPBACK);Check(!bind(listener,(sockaddr*)&address,sizeof(address))&&!listen(listener,8),"Original HTTP loopback bind failed");int length=sizeof(address);Check(!getsockname(listener,(sockaddr*)&address,&length),"Original HTTP port failed");port=ntohs(address.sin_port);
  worker=std::thread([this]{try{while(!stop){fd_set ready;FD_ZERO(&ready);FD_SET(listener,&ready);timeval timeout={0,200000};auto selected=select(0,&ready,nullptr,nullptr,&timeout);if(stop)break;if(selected<=0)continue;auto s=accept(listener,nullptr,nullptr);if(s==INVALID_SOCKET){if(stop)break;throw std::runtime_error("HTTP fixture accept failed");}peer=s;DWORD receiveTimeout=5000;setsockopt(s,SOL_SOCKET,SO_RCVTIMEO,(const char*)&receiveTimeout,sizeof(receiveTimeout));std::string header;char c;
   while(header.find("\r\n\r\n")==std::string::npos){Check(header.size()<65536&&recv(s,&c,1,0)==1,"HTTP fixture header failed");header+=c;}auto first=header.find(' '),second=header.find(' ',first+1);Check(first!=std::string::npos&&second!=std::string::npos,"HTTP request line malformed");auto path=header.substr(first+1,second-first-1);auto lower=header;std::transform(lower.begin(),lower.end(),lower.begin(),[](unsigned char v){return (char)tolower(v);});size_t bodySize=0;auto position=lower.find("\r\ncontent-length:");if(position!=std::string::npos)bodySize=std::stoul(lower.substr(position+17));Check(bodySize<=4096,"HTTP fixture body exceeded bound");std::string body(bodySize,'\0');size_t done=0;while(done<bodySize){int count=recv(s,&body[done],(int)(bodySize-done),0);Check(count>0,"HTTP fixture body truncated");done+=count;}
   ++requests;bool redirect=path.find("redirect")!=std::string::npos;std::string value=path=="/post"?"echo:"+body:payload;std::string response="HTTP/1.1 "+std::string(redirect?"302 Found":"200 OK")+"\r\nContent-Type: text/plain\r\nConnection: close\r\n";if(redirect){response+="Location: https://not-the-configured-host.invalid/no\r\n";value.clear();}response+="Content-Length: "+std::to_string(value.size())+"\r\n\r\n"+value;done=0;while(done<response.size()){int count=send(s,response.data()+done,(int)(response.size()-done),0);Check(count>0,"HTTP fixture response failed");done+=count;}shutdown(s,SD_BOTH);closesocket(s);peer=INVALID_SOCKET;
  }}catch(const std::exception& e){if(!stop){std::cout<<"HTTP fixture: "<<e.what()<<"\n";valid=false;}}});
 }
 ~Server(){stop=true;if(listener!=INVALID_SOCKET)closesocket(listener);auto s=peer.load();if(s!=INVALID_SOCKET)shutdown(s,SD_BOTH);if(worker.joinable())worker.join();s=peer.exchange(INVALID_SOCKET);if(s!=INVALID_SOCKET)closesocket(s);}
};
static std::string ReadHttp(HINTERNET request){std::string output;char buffer[64];DWORD count=0;do{Check(HTTP(WinHttpReadData)(request,buffer,sizeof(buffer),&count),"Actual native WinHTTP read failed");output.append(buffer,count);}while(count);return output;}
static DWORD StatusHttp(HINTERNET request){DWORD code=0,size=sizeof(code);Check(HTTP(WinHttpQueryHeaders)(request,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,nullptr,&code,&size,nullptr),"Actual native WinHTTP status failed");return code;}
