 Server server;Check(HWConfigureNetwork(L"127.0.0.1",server.port),"Own HTTP policy setup failed");const char* httpNames[]={"WinHttpAddRequestHeaders","WinHttpCloseHandle","WinHttpConnect","WinHttpCrackUrl","WinHttpGetProxyForUrl","WinHttpOpen","WinHttpOpenRequest","WinHttpQueryHeaders","WinHttpReadData","WinHttpReceiveResponse","WinHttpSendRequest","WinHttpSetTimeouts","WinHttpWriteData"};for(auto name:httpNames)Check(ResolveWebImport("winhttp.dll",name)!=nullptr,"Required WinHTTP binding missing");
 const char* inetNames[]={"HttpOpenRequestW","HttpQueryInfoW","HttpSendRequestW","InternetCloseHandle","InternetConnectW","InternetOpenW","InternetQueryOptionA","InternetReadFile","InternetSetOptionA"};for(auto name:inetNames)Check(ResolveWebImport("wininet.dll",name)!=nullptr,"Required WinINet binding missing");Check(!ResolveWebImport("winhttp.dll","WinHttpSetOption")&&!ResolveWebImport("wininet.dll","InternetOpenUrlW"),"Unscoped transport entry exposed");
