 request=HTTP(WinHttpOpenRequest)(connection,L"POST",L"/post",nullptr,nullptr,nullptr,0);Check(request&&HTTP(WinHttpSendRequest)(request,nullptr,0,nullptr,0,4,0),"Actual WinHTTP streamed request start failed");DWORD written=0;Check(HTTP(WinHttpWriteData)(request,"body",4,&written)&&written==4&&HTTP(WinHttpReceiveResponse)(request,nullptr)&&ReadHttp(request)=="echo:body","Native WinHTTP WriteData/body echo failed");HTTP(WinHttpCloseHandle)(request);
 request=HTTP(WinHttpOpenRequest)(connection,L"GET",L"/http-redirect",nullptr,nullptr,nullptr,0);Check(request&&HTTP(WinHttpSendRequest)(request,nullptr,0,nullptr,0,0,0)&&HTTP(WinHttpReceiveResponse)(request,nullptr)&&StatusHttp(request)==302,"Native WinHTTP followed an unauthorized redirect");HTTP(WinHttpCloseHandle)(request);
 URL_COMPONENTS parts={};parts.dwStructSize=sizeof(parts);parts.dwHostNameLength=(DWORD)-1;Check(HTTP(WinHttpCrackUrl)(L"https://fixture.invalid/path",0,0,&parts)&&parts.nPort==443&&parts.dwHostNameLength==15,"Actual OS URL parser failed");WINHTTP_AUTOPROXY_OPTIONS options={};options.dwFlags=WINHTTP_AUTOPROXY_AUTO_DETECT;WINHTTP_PROXY_INFO proxy={};Check(!HTTP(WinHttpGetProxyForUrl)(session,L"https://not-allowed.invalid/",&options,&proxy)&&GetLastError()==ERROR_ACCESS_DENIED,"Auto-proxy discovery bypass admitted");
 auto open=Api<OpenInet>("WININET.dll","InternetOpenW");auto connect=Api<ConnectInet>("WININET.dll","InternetConnectW");auto make=Api<RequestInet>("WININET.dll","HttpOpenRequestW");auto send=Api<SendInet>("WININET.dll","HttpSendRequestW");auto query=Api<QueryInet>("WININET.dll","HttpQueryInfoW");auto read=Api<ReadInet>("WININET.dll","InternetReadFile");auto close=Api<CloseInet>("WININET.dll","InternetCloseHandle");auto set=Api<SetInet>("WININET.dll","InternetSetOptionA");auto get=Api<OptionInet>("WININET.dll","InternetQueryOptionA");auto inet=open(L"HollowwakeOwnedFixture",1,nullptr,nullptr,0);Check(inet,"Actual WinINet session failed");DWORD timeout=5000,size=sizeof(timeout),observed=0;Check(set(inet,2,&timeout,sizeof(timeout))&&get(inet,2,&observed,&size)&&observed==timeout,"Native WinINet option state differs");Check(!set(inet,31,&timeout,sizeof(timeout))&&GetLastError()==ERROR_ACCESS_DENIED,"TLS validation policy override admitted");Check(!connect(inet,L"not-allowed.invalid",443,nullptr,nullptr,3,0,0)&&GetLastError()==ERROR_ACCESS_DENIED,"WinINet unapproved host admitted");auto ic=connect(inet,L"127.0.0.1",server.port,nullptr,nullptr,3,0,0);Check(ic,"Actual WinINet connection handle failed");Check(!make(ic,L"GET",L"/read",nullptr,nullptr,nullptr,0x00003000,0)&&GetLastError()==ERROR_ACCESS_DENIED,"WinINet certificate-ignore flags admitted");
 auto ir=make(ic,L"GET",L"/read",nullptr,nullptr,nullptr,0,0);Check(ir&&send(ir,nullptr,0,nullptr,0),"Native WinINet send failed");DWORD status=0;size=sizeof(status);Check(query(ir,19|0x20000000,&status,&size,nullptr)&&status==200,"Native WinINet status parsing failed");std::string output;char buffer[64];DWORD count=0;do{Check(read(ir,buffer,sizeof(buffer),&count),"Native WinINet read failed");output.append(buffer,count);}while(count);Check(output==server.payload,"WinINet did not return actual fixture bytes");Check(!HTTP(WinHttpCloseHandle)(ir)&&GetLastError()==ERROR_INVALID_HANDLE,"Cross-provider handle admitted");close(ir);
