 Check(HWConfigureNetwork(L"backend.invalid",443),"Remote policy setup failed");auto remote=HTTP(WinHttpConnect)(session,L"backend.invalid",443,0);Check(remote&&!HTTP(WinHttpOpenRequest)(remote,L"GET",L"/",nullptr,nullptr,nullptr,0)&&GetLastError()==ERROR_ACCESS_DENIED,"Remote plaintext request admitted");HTTP(WinHttpCloseHandle)(remote);Check(!read(ir,buffer,sizeof(buffer),&count)&&GetLastError()==ERROR_ACCESS_DENIED,"Changed-origin handle remained usable");
